#include <iostream>
#include <vector>
#include <utility>

long long total(const std::vector<int>& v)
{
    long long s{};
    for (int x : v) s += x;
    return s;
}

void addToAll(std::vector<int>& v, int d)
{
    for (int& x : v) x += d;
}

void reverseIt(std::vector<int>& v)
{
    std::size_t i{ 0 };
    std::size_t j{ v.size() };
    while (i + 1 < j)
    {
        std::swap(v[i], v[j - 1]);
        ++i;
        --j;
    }
}

void printAll(const char* label, const std::vector<int>& v)
{
    std::cout << label;
    for (std::size_t i = 0; i < v.size(); ++i)
        std::cout << ' ' << v[i];
    std::cout << "\n";
}

int main()
{
    int n{};
    if (!(std::cin >> n)) return 0;

    std::vector<int> v;
    for (int i = 0; i < n; ++i)
    {
        int x{};
        std::cin >> x;
        v.push_back(x);
    }

    std::cout << "total " << total(v) << "\n";
    addToAll(v, 7);
    printAll("after-add", v);
    reverseIt(v);
    printAll("reversed", v);
    std::cout << "total " << total(v) << "\n";

    return 0;
}
